		ImagingCenter parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Facility on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Facility on the parent entithy
		// ------------------------------------------     
	    parentEntity.setFacility(null);

